/**
 * Searches the DOM element, containerElement, for all descendants that are fields that can be validated
 * and runs their validation functions which will put any error messages up on the screen
 * as well as return whether all elements are valid within the container or not.
 * @param containerElement: a DOM element - You need to pass in a container that contains basic Neon input fields.
 *                                 validateElements(document.querySelector('neon-text-field'))  <-- Does not actually validate that text widget.
 *                                 You need to pass in the container that holds the neon-text-field.
 *                               - Takes undefined and null as options so you can easily pass in the result of document.querySelector()
 *                                 Example: validateElements(document.querySelector('something'))  Returns true when this gets passed in.
 * @param setFocus: When true, this will set focus on the first invalid field in the form.  Defaults to true.
 * @returns true if all the elements are valid OR you didn't pass in an actual HTML Element.
 *          false if one or more elements are NOT valid.
 */
export function validateFields(containerElement, setFocus) {
    if (containerElement == null) {
        return true;
    }
    if (setFocus == null) {
        setFocus = true;
    }
    let allElementsAreValid = true;
    const inputWidgets = containerElement.querySelectorAll('[neon-2_20_1-input-field]');
    for (let i = 0; i < inputWidgets.length; i++) {
        //It's important that the AND allElementsAreValid is tested AFTER numWidgets[i].validateNumber
        //so ALL elements will be validated.
        //The parameter to validateWidget here could come from parameters of this method to enable us
        //to tell the widget whether or not it should show errors after validation.
        allElementsAreValid = inputWidgets[i].validateWidget(true) && allElementsAreValid;
    }
    // if there are invalid elements, then set focus on the first invalid element
    if (!allElementsAreValid && setFocus) {
        setFocusOnFirstInvalidElement(containerElement);
    }
    return allElementsAreValid;
}
/**
 * Searches the DOM element, containerElement, for all descendants that are fields that can be validated
 * and runs their validation functions which can show (or not) error message on the screen
 * as well as returns information about the validity of the elements.
 * @note If you just need to validate some fields in a container, you probably should run validateFields().
 * You should use validateFields2() if you want to skip showing isRequired errors, or you want to
 * know how many isRequired errors are showing up compared to how many total errors there are.
 *
 * @param containerElement: The container to search for input fields.
 * @param showErrors: 'all-errors' -> makes normal errors, and required errors show up on the fields if they are invalid.
 *                   'non-required-errors' -> Makes normal errors, but not isRequired errors, show up on the fields if they are invalid.
 *                   'no-errors' -> Prevents errors being shown on the fields as a result of running this function
 * @param setFocus: When set to true, the first invalid field will get focus.  Defaults to true.
 * @returns The ValidationFieldResult object that describes the state of the validation.
 */
export function validateFields2(containerElement, showErrors, setFocus) {
    const showErrorsUnderField = showErrors === 'all-errors' || showErrors === 'non-required-errors';
    const showIsRequiredErrors = showErrors === 'all-errors';
    if (containerElement == null) {
        return {
            isValid: true,
            totalInvalidFields: 0,
            emptyInvalidFields: 0
        };
    }
    if (setFocus == null) {
        setFocus = true;
    }
    const overallErrorState = {
        isValid: true,
        totalInvalidFields: 0,
        emptyInvalidFields: 0
    };
    const inputWidgets = containerElement.querySelectorAll('[neon-2_20_1-input-field]');
    for (let i = 0; i < inputWidgets.length; i++) {
        //It's important that the AND allElementsAreValid is tested AFTER numWidgets[i].validateNumber
        //so ALL elements will be validated.
        //The parameter to validateWidget here could come from parameters of this method to enable us
        //to tell the widget whether or not it should show errors after validation.
        const isFieldValid = inputWidgets[i].validateWidget(showErrorsUnderField, undefined, showIsRequiredErrors);
        if (!isFieldValid) {
            overallErrorState.isValid = false;
            overallErrorState.totalInvalidFields++;
            if (inputWidgets[i].invalidRule === 'isRequired') {
                overallErrorState.emptyInvalidFields++;
            }
        }
    }
    // if there are invalid elements, then set focus on the first invalid element
    if (!overallErrorState.isValid && setFocus && overallErrorState.totalInvalidFields > overallErrorState.emptyInvalidFields) {
        setFocusOnFirstInvalidElement(containerElement);
    }
    return overallErrorState;
}
/**
 * This function returns a list of invalid elements that are contained within some parent element.
 * @param page
 * @return list of invalid elements
 */
export function getAllInvalidElements(parentElement) {
    const myInvalidElements = new Array();
    const allMyChildInputElements = parentElement.querySelectorAll('[neon-2_20_1-input-field]');
    for (let i = 0; i < allMyChildInputElements.length; i++) {
        if (!allMyChildInputElements[i].validateWidget(true)) {
            myInvalidElements.push(allMyChildInputElements[i]);
        }
    }
    return myInvalidElements;
}
/**
 * This function returns the first invalid element on the page
 * @param page
 * @return list of invalid elements
 */
export function getFirstInvalidElement(parentElement) {
    let myFirstInvalidElement;
    const allMyChildInputElements = parentElement.querySelectorAll('[neon-2_20_1-input-field]');
    for (let i = 0; i < allMyChildInputElements.length; i++) {
        if (!allMyChildInputElements[i].validateWidget(true)) {
            myFirstInvalidElement = allMyChildInputElements[i];
            return myFirstInvalidElement;
        }
    }
    return myFirstInvalidElement;
}
/**
 * sets focus on the first invalid element
 */
export function setFocusOnFirstInvalidElement(parentElement) {
    const myFirstInvalidElement = getFirstInvalidElement(parentElement);
    if (myFirstInvalidElement != null) {
        const focusableElement = myFirstInvalidElement.querySelector('input,a,button');
        if (focusableElement != null) {
            focusableElement.focus();
        }
    }
}
/**
 * Resets the validation on the fields within the container, clearing all validation messages.
 * The fields will continue to know whether they are valid or not internally.
 * @param containerElement: The container to search.
 */
export function resetFieldValidation(containerElement) {
    if (containerElement == null) {
        return;
    }
    const inputWidgets = containerElement.querySelectorAll('[neon-2_20_1-input-field]');
    for (let i = 0; i < inputWidgets.length; i++) {
        inputWidgets[i].resetValidation();
    }
}
/**
 * Counts the number of non-empty fields within a container element.
 *
 * @param containerElement: The container element to search for non-empty fields.
 * @returns The number of non-empty fields found.
 */
export function getNonEmptyFieldCount(containerElement) {
    if (containerElement == null) {
        return 0;
    }
    let nonEmptyFields = 0;
    const allMyChildInputElements = containerElement.querySelectorAll('[neon-2_20_1-input-field]');
    for (let i = 0; i < allMyChildInputElements.length; i++) {
        const inputModelValue = allMyChildInputElements[i].modelValue;
        if (inputModelValue == null || inputModelValue === '') {
            continue;
        }
        if (Array.isArray(inputModelValue) && inputModelValue.length === 0) {
            continue;
        }
        nonEmptyFields++;
    }
    return nonEmptyFields;
}
